// Format HTML message for Telegram based on payload type
const alertData = $('Alert Webhook').first().json.body || $('Alert Webhook').first().json;
const settings = $input.first().json;

const botToken = settings.telegram_bot_token;
const chatId = settings.telegram_chat_id;
const alertType = alertData.type || (alertData.order_number ? 'new_order' : 'new_complaint');

let htmlMessage = '';

if (alertType === 'new_order') {
  const orderNo = alertData.order_number || alertData.id?.slice(0, 8) || 'N/A';
  const name = alertData.customer_name || 'عميل';
  const phone = alertData.customer_phone || 'غير مسجل';
  const address = alertData.delivery_address || 'استلام من الفرع';
  const total = alertData.total_amount || alertData.subtotal || '0';

  let itemsList = '';
  if (Array.isArray(alertData.items) && alertData.items.length > 0) {
    itemsList = alertData.items.map(it => `• <b>${it.item_name || it.name}</b> x${it.quantity || 1} (${it.unit_price || it.price} ج)`).join('\n');
  } else {
    itemsList = alertData.items_summary || '• أصناف متنوعة';
  }

  htmlMessage = `🛒 <b>أوردر جديد من فيسبوك بوت #ORD-${orderNo}</b>\n` +
    `━━━━━━━━━━━━━━━━━━\n` +
    `👤 <b>العميل:</b> ${name}\n` +
    `📞 <b>الهاتف:</b> <a href="tel:${phone}">${phone}</a>\n` +
    `📍 <b>العنوان:</b> ${address}\n\n` +
    `📋 <b>الأصناف المطلوبة:</b>\n${itemsList}\n\n` +
    `💰 <b>الإجمالي المطلوب:</b> <b>${total} ج.م</b> (شامل التوصيل)\n` +
    `⏰ <b>الوقت:</b> ${new Date().toLocaleTimeString('ar-EG')}\n` +
    `━━━━━━━━━━━━━━━━━━\n` +
    `👉 <i>يرجى المتابعة وتأكيد التحضير من شاشة الأوردرات</i>`;
} else {
  const ticketNo = alertData.ticket_number || alertData.id?.slice(0, 8) || '101';
  const name = alertData.customer_name || 'عميل';
  const phone = alertData.customer_phone || 'غير مسجل';
  const priority = alertData.priority === 'urgent' ? '🔴 عاجل جداً' : (alertData.priority === 'high' ? '🟠 أولوية عالية' : '🟡 عادي');
  const issue = alertData.issue_description || alertData.message || 'طلب مساعدة فورية';

  htmlMessage = `⚠️ <b>تذكرة شكوى / طلب مساعدة #CMP-${ticketNo}</b>\n` +
    `━━━━━━━━━━━━━━━━━━\n` +
    `🚨 <b>درجة الأهمية:</b> ${priority}\n` +
    `👤 <b>العميل:</b> ${name}\n` +
    `📞 <b>الهاتف:</b> <a href="tel:${phone}">${phone}</a>\n\n` +
    `📝 <b>تفاصيل الشكوى:</b>\n<i>${issue}</i>\n\n` +
    `⏰ <b>الوقت:</b> ${new Date().toLocaleTimeString('ar-EG')}\n` +
    `━━━━━━━━━━━━━━━━━━\n` +
    `👉 <i>يرجى الدخول فوراً للداشبورد ومتابعة العميل</i>`;
}

return [{
  json: {
    bot_token: botToken,
    chat_id: chatId,
    formatted_message: htmlMessage
  }
}];
